def transform(grid):
    h,w=len(grid),len(grid[0])
    marker=min(set(x for row in grid for x in row)) if False else None
    # In these task variants, the rare foreground is the non-background color; infer by frequency.
    from collections import Counter
    cnt=Counter(x for row in grid for x in row)
    bg=cnt.most_common(1)[0][0]
    out=[row[:] for row in grid]
    for r,row in enumerate(grid):
        pos=[c for c,x in enumerate(row) if x!=bg]
        if len(pos)>=2:
            for c in range(min(pos)+1,max(pos)):
                if out[r][c]==bg: out[r][c]=3
    for c in range(w):
        pos=[r for r in range(h) if grid[r][c]!=bg]
        if len(pos)>=2:
            for r in range(min(pos)+1,max(pos)):
                if out[r][c]==bg: out[r][c]=3
    return out
